 1	// RUN: %dafny /compile:0 /dprint:"%t.dprint" "%s" > "%t"
 2	// RUN: %diff "%s.expect" "%t"
 3	
 4	function Factorial(n: nat): nat
 5	{
 6	  if n == 0 then 1 else n * Factorial(n-1)
 7	}
 8	
 9	method ComputeFactorial(n: int) returns (u: int)
10	  requires 1 <= n;
11	  ensures u == Factorial(n);
12	{
13	  var r := 1;
14	  u := 1;
15	  while (r < n)
16	    invariant r <= n;
17	    invariant u == Factorial(r);
18	  {
19	    var v, s := u, 1;
20	    while (s < r + 1)
21	      invariant v == Factorial(r) && u == s * Factorial(r);
22	    {
23	      u := u + v;
24	      s := s + 1;
25	    }
26	    r := r + 1;
27	  }
28	}
29

